-- 90-Day Gameplan: Nov 8, 2026 to Feb 5, 2027: models part 3 of 4
-- Run in the MAISON DE VEUX Supabase project (SQL Editor). Safe to run again: every row made by this plan has a key
-- (metadata.gp_key), so a second run updates dates and text and never duplicates or resets a status.
-- Needs: the team names Emma, Erica, Troy and Sophia as active staff with a display name (first name matched).
-- Models are matched by name. Anyone not found is listed in the Messages tab as a NOTICE and skipped.

create or replace function pg_temp.nm(t text) returns text language sql immutable as $f$
  select coalesce(string_agg(x, ' ' order by x), '')
  from unnest(regexp_split_to_array(lower(regexp_replace(trim(coalesce(t, '')), '[^a-zA-Z0-9 ]', '', 'g')), '\s+')) x
$f$;

create or replace function pg_temp.gp_item(org uuid, boss uuid, mid uuid, gp uuid, pa uuid, it jsonb, mem jsonb)
returns text language plpgsql as $f$
declare
  tid uuid; eid uuid; own text; mm uuid; v_model uuid; v_partner uuid; v_vis text; v_meta jsonb; prio text;
  aud text := it->>'a';
begin
  if it->>'k' = 't' then
    if aud = 'partner' and pa is null then return 'skip:nopartner'; end if;
    prio := case when (it->>'h')::boolean then 'high' else 'normal' end;
    v_model := case when aud = 'model' then mid else null end;
    v_partner := case when aud = 'partner' then pa else null end;
    v_vis := case when aud = 'partner' then 'partner_shared' else 'organization' end;
    v_meta := jsonb_build_object('gp_key', it->>'i', 'plan', 'g90', 'task_type', it->>'ty', 'is_hard_stop', (it->>'h')::boolean,
                                 'area', it->>'ar', 'owner_name', it->>'o', 'due_label', it->>'w', 'audience', aud);
    if aud = 'model' then v_meta := v_meta || jsonb_build_object('gameplan_id', gp); end if;
    if it ? 'amt' then v_meta := v_meta || jsonb_build_object('approval_amount', it->'amt'); end if;
    if it ? 'ms' then v_meta := v_meta || jsonb_build_object('models', it->'ms'); end if;
    select id into tid from public.tasks where organization_id = org and metadata->>'gp_key' = it->>'i' limit 1;
    if tid is null then
      insert into public.tasks (organization_id, model_id, partner_agency_id, title, description, priority, due_at, category, status, visibility, created_by, metadata)
      values (org, v_model, v_partner, it->>'t', it->>'d', prio, (it->>'u')::timestamptz, it->>'ty', 'open', v_vis, boss, v_meta)
      returning id into tid;
      if aud = 'model' then
        insert into public.task_assignments (organization_id, task_id, model_id, assignment_role, assigned_by) values (org, tid, mid, 'assignee', boss) on conflict do nothing;
      elsif aud = 'staff' then
        own := lower(split_part(it->>'o', ' ', 1));
        if mem ? own then
          insert into public.task_assignments (organization_id, task_id, member_id, assignment_role, assigned_by) values (org, tid, (mem->>own)::uuid, 'assignee', boss) on conflict do nothing;
        else
          return 'task:nomember:' || own;
        end if;
      end if;
    else
      update public.tasks set title = it->>'t', description = it->>'d', priority = prio, due_at = (it->>'u')::timestamptz, category = it->>'ty',
             metadata = coalesce(metadata, '{}'::jsonb) || v_meta, updated_at = now()
      where id = tid;
    end if;
    return 'task';
  elsif it->>'k' = 'e' then
    v_meta := jsonb_build_object('gp_key', it->>'i', 'plan', 'g90', 'category', it->>'ar', 'event_kind', it->>'ek', 'calendar_event_type', it->>'ty');
    select id into eid from public.events where organization_id = org and metadata->>'gp_key' = it->>'i' limit 1;
    if eid is null then
      insert into public.events (organization_id, title, event_type, status, starts_at, ends_at, timezone, all_day, location, visibility, notes, metadata)
      values (org, it->>'t', it->>'ty', 'scheduled', (it->>'u')::timestamptz, nullif(it->>'en', '')::timestamptz, it->>'z', false, it->>'loc', 'model_shared', it->>'d', v_meta)
      returning id into eid;
    else
      update public.events set title = it->>'t', event_type = it->>'ty', starts_at = (it->>'u')::timestamptz, ends_at = nullif(it->>'en', '')::timestamptz,
             timezone = it->>'z', location = it->>'loc', notes = it->>'d', metadata = coalesce(metadata, '{}'::jsonb) || v_meta, updated_at = now()
      where id = eid;
    end if;
    insert into public.event_models (organization_id, event_id, model_id) values (org, eid, mid) on conflict do nothing;
    return 'event';
  end if;
  return 'skip';
end $f$;

do $gp$
declare
  p jsonb := $json${"models":[{"name":"Akvile Kerpauskaite","gp":{"title":"90-Day Gameplan: Nov 8, 2026 to Feb 5, 2027","key_date":"2027-01-25","key_label":"Paris Haute Couture SS27","welcome":"Welcome to your 90-day gameplan, Akvile. Every task has a date and a time in your own time zone. Tap Complete when a task is done, or request a new date with a note. Your agent is Erica.","positioning":"Runway: Paris Haute Couture SS27 (Mon Jan 25 to Thu Jan 28); Paris Women's FW27-28 (Mon Mar 1 to Tue Mar 9).","market":"Base: Amsterdam. Shows: Paris Haute Couture SS27, Paris Women's FW27-28.","image_rules":"Test shoots: 2 in this block. Fresh digitals close to your first show. Skin photos four times (Nov 16, Dec 14, pre-show, Feb 1). Nothing is posted or sent without your approval of the selects.","risks":"","cadence":{"daily":"Skin routine morning and night, food and water, sleep 8 hours","walk":"Tuesday and Thursday 30 minutes","weekly":"Sunday wellness check-in with your agent","deadlines":"All dates and times are in your gameplan tasks"}},"ds":{"built":"2026-11-08","until":"2027-02-05","blocks":[{"id":"gp_snack1","days":["0","1","2","3","4","5","6"],"start":"10:30","end":"10:45","title":"Snack + water (fueling plan)","cat":"meal","until":"2027-02-05"},{"id":"gp_snack2","days":["0","1","2","3","4","5","6"],"start":"15:30","end":"15:45","title":"Snack + water (fueling plan)","cat":"meal","until":"2027-02-05"},{"id":"gp_walk","days":["2","4"],"start":"18:00","end":"18:30","title":"Walk practice (gameplan)","cat":"model","until":"2027-02-05"},{"id":"gp_checkin","days":["0"],"start":"17:00","end":"17:20","title":"Sunday wellness check-in with your agent","cat":"routine","until":"2027-02-05"}],"habits":[{"id":"gp_skin","label":"Skin plan from your gameplan: morning and night"},{"id":"gp_fuel","label":"Fueling plan: protein at every meal, two snacks, water"},{"id":"gp_walk","label":"Walk practice Tuesday and Thursday"},{"id":"gp_sleep","label":"Sleep 8 hours"}],"weekly":[{"k":"gp_dates","t":"Open your gameplan: skin photos, walk videos, health checks and test shoots each have a set date and time"},{"k":"gp_walkvid","t":"Walk video due dates: Nov 23, Dec 14 and your pre-show date"}]},"items":[{"i":"g90:akvile-kerpauskaite:PLAN","a":"staff","o":"Erica","t":"Gameplan live for Akvile Kerpauskaite","d":"Check that the model sees the gameplan, the mother agency has partner tasks, and the DaySilk events appear.","u":"2026-11-10T17:00:00Z","k":"t","ty":"agent","h":true,"ar":"Gameplan","z":"America/New_York","w":"Tue Nov 10, 12:00 PM ET"},{"i":"g90:akvile-kerpauskaite:G1","a":"model","o":"Akvile Kerpauskaite","t":"Confirm your gameplan and shows","d":"Open your gameplan, read the dates, and tap Complete to confirm. Shows: Paris Haute Couture SS27, Paris Women's FW27-28.","u":"2026-11-13T16:00:00Z","k":"t","ty":"agent","h":false,"ar":"Gameplan","z":"Europe/Paris","w":"Fri Nov 13, 5:00 PM Paris (Fri Nov 13 11:00 AM ET)"},{"i":"g90:akvile-kerpauskaite:SK1","a":"model","o":"Akvile Kerpauskaite","t":"Skin submission #1 (baseline): photos due","d":"Skin submission = 4 photos in daylight by a window, no makeup, no filter, no retouching: front, left, right, and a close-up of any area you want help with. Add three lines: skin type as you see it, any concerns, and any product reaction. A licensed skin professional reviews it. You can choose to share only the photos and not any medical history. Due Mon Nov 16, 5:00 PM Paris (Mon Nov 16 11:00 AM ET).","u":"2026-11-16T16:00:00Z","k":"t","ty":"progress_submission","h":false,"ar":"Skin","z":"Europe/Paris","w":"Mon Nov 16, 5:00 PM Paris (Mon Nov 16 11:00 AM ET)"},{"i":"g90:akvile-kerpauskaite:SK1e","a":"model","o":"Akvile Kerpauskaite","t":"Skin submission #1 due","d":"Upload your skin photos in the portal today.","u":"2026-11-16T16:00:00Z","k":"e","ty":"deadline","h":false,"ar":"Skin","z":"Europe/Paris","w":"Mon Nov 16, 5:00 PM Paris (Mon Nov 16 11:00 AM ET)","en":null,"loc":null,"ek":"model meeting"},{"i":"g90:akvile-kerpauskaite:PA1","a":"partner","o":"Mother agency","t":"Confirm representation and show list (Akvile Kerpauskaite)","d":"Confirm who represents the model for each market and which shows are approved.","u":"2026-11-18T17:00:00Z","k":"t","ty":"agent","h":false,"ar":"Gameplan","z":"America/New_York","w":"Wed Nov 18, 12:00 PM ET"},{"i":"g90:akvile-kerpauskaite:H1","a":"model","o":"Akvile Kerpauskaite","t":"Health intake: allergies, food limits, injuries","d":"Fill in the short intake form: allergies, food limits, injuries and anything you want us to plan around. You choose what to share. We never ask for weight or body-measurement targets.","u":"2026-11-20T16:00:00Z","k":"t","ty":"progress_submission","h":false,"ar":"Health","z":"Europe/Paris","w":"Fri Nov 20, 5:00 PM Paris (Fri Nov 20 11:00 AM ET)"},{"i":"g90:akvile-kerpauskaite:SKP","a":"model","o":"Akvile Kerpauskaite","t":"Start your skin plan: read and confirm","d":"Every day: AM gentle cleanser, moisturizer, broad-spectrum SPF 30+. PM: remove sunscreen and makeup fully (double cleanse on shoot days), then moisturizer. Once a week: one gentle exfoliation and one hydrating mask. Patch-test anything new on the jaw for 3 days. Never sleep in makeup. If you shave, use a clean blade, shave with the grain and finish with an alcohol-free soother. Climate: cool, damp winter and indoor heating. Use a ceramide cream at night, run a humidifier where you sleep, and keep SPF on even when it is cloudy. Pre-show protocol (starts 14 days before your first show): no new active products, no peels, lasers, waxing or fillers in the last 7 days, no sunburn or tanning, sleep 8 hours, and remove all makeup at the end of every day. If anything flares, tell your agent the same day. Travel days: cleanse, put on a thick moisturizer, no new products, drink water through the flight, and use a hydrating mask after landing. Skin submission = 4 photos in daylight by a window, no makeup, no filter, no retouching: front, left, right, and a close-up of any area you want help with. Add three lines: skin type as you see it, any concerns, and any product reaction. A licensed skin professional reviews it. You can choose to share only the photos and not any medical history.","u":"2026-11-23T16:00:00Z","k":"t","ty":"progress_submission","h":false,"ar":"Skin","z":"Europe/Paris","w":"Mon Nov 23, 5:00 PM Paris (Mon Nov 23 11:00 AM ET)"},{"i":"g90:akvile-kerpauskaite:WK1","a":"model","o":"Akvile Kerpauskaite","t":"Walk video #1: send your 20-second walk","d":"Walk practice, 30 minutes, Tuesday and Thursday. Warm up 5 minutes. Straight-line walk of 10 to 15 steps with level eyes and shoulders back, a clean turn at the end, pause, turn back. Practice in the shoe height you expect to wear. Film one 20-second clip from the front and one from the side, phone at hip height, plain background, full body in frame. Your agent gives written feedback and one drill for the next week. Due Mon Nov 23, 5:00 PM Paris (Mon Nov 23 11:00 AM ET).","u":"2026-11-23T16:00:00Z","k":"t","ty":"training","h":false,"ar":"Walk","z":"Europe/Paris","w":"Mon Nov 23, 5:00 PM Paris (Mon Nov 23 11:00 AM ET)"},{"i":"g90:akvile-kerpauskaite:WK1e","a":"model","o":"Akvile Kerpauskaite","t":"Walk practice video #1 due","d":"Send your walk video in the portal today.","u":"2026-11-23T16:00:00Z","k":"e","ty":"training","h":false,"ar":"Walk","z":"Europe/Paris","w":"Mon Nov 23, 5:00 PM Paris (Mon Nov 23 11:00 AM ET)","en":null,"loc":null,"ek":"walk practice"},{"i":"g90:akvile-kerpauskaite:TS1-team","a":"staff","o":"Erica","t":"Test shoot 1: lock photographer, MUA, stylist and studio (Akvile)","d":"Shoot is Tue Dec 8, 2026, 9:00 AM Paris at Amsterdam studio. Book photographer, makeup, hair, stylist and studio, send the mood board to Akvile and the mother agency, and confirm wardrobe. HARD STOP: shoot cannot slip after this time.","u":"2026-11-24T17:00:00Z","k":"t","ty":"testing","h":true,"ar":"Test shoot","z":"America/New_York","w":"Tue Nov 24, 12:00 PM ET"},{"i":"g90:akvile-kerpauskaite:FUEL","a":"model","o":"Akvile Kerpauskaite","t":"Your fueling plan: read it and send allergies or food limits","d":"This is healthy fueling, not dieting. Three meals and two snacks a day, protein at every meal, a vegetable or fruit at most meals, whole grains or starch for energy on training and walk-practice days, and 2 to 3 liters of water. No crash dieting, cleanses, diet pills or skipped meals. MDV does not set weight or measurement targets for any model. If a doctor or dietitian gives you a plan, that plan wins. Tell us any allergies or food limits in your health intake so this plan fits you. Easy picks: eggs, yogurt or skyr, oats, fish, lentil or bean soups, whole-grain bread, roasted vegetables and fruit. In Paris, bakeries and markets make it simple to pair a protein with a fruit or vegetable. Show weeks: carry snacks (nuts, fruit, a protein bar, a sandwich), eat before every call time, keep water with you, and keep caffeine and alcohol low the night before a casting or show.","u":"2026-11-25T16:00:00Z","k":"t","ty":"training","h":false,"ar":"Diet","z":"Europe/Paris","w":"Wed Nov 25, 5:00 PM Paris (Wed Nov 25 11:00 AM ET)"},{"i":"g90:akvile-kerpauskaite:PA3","a":"partner","o":"Mother agency","t":"Sign off the gameplan and test shoot plan (Akvile Kerpauskaite)","d":"Review the gameplan, test shoot dates and image rules, then approve or comment.","u":"2026-11-25T17:00:00Z","k":"t","ty":"agent","h":false,"ar":"Gameplan","z":"America/New_York","w":"Wed Nov 25, 12:00 PM ET"},{"i":"g90:akvile-kerpauskaite:TS1-concept","a":"partner","o":"Mother agency","t":"Approve test shoot 1 concept (Akvile Kerpauskaite)","d":"Please approve or comment on the concept and looks for the test shoot on Tue Dec 8, 2026.","u":"2026-12-01T17:00:00Z","k":"t","ty":"testing","h":false,"ar":"Test shoot","z":"America/New_York","w":"Tue Dec 1, 12:00 PM ET"},{"i":"g90:akvile-kerpauskaite:TS1-confirm","a":"model","o":"Akvile Kerpauskaite","t":"Confirm your test shoot 1 call sheet","d":"Tap Complete when you have read the call sheet and confirm you can be there at 9:00 AM on Tue Dec 8, 2026. Skin prep: no new products, no waxing, sleep 8 hours.","u":"2026-12-04T16:00:00Z","k":"t","ty":"testing","h":false,"ar":"Test shoot","z":"Europe/Paris","w":"Fri Dec 4, 5:00 PM Paris (Fri Dec 4 11:00 AM ET)"},{"i":"g90:akvile-kerpauskaite:TS1-callsheet","a":"staff","o":"Erica","t":"Test shoot 1: send call sheet (Akvile)","d":"Call sheet to Akvile and mother agency: address, call time 9:00 AM Paris, wardrobe, skin prep and what to eat.","u":"2026-12-04T17:00:00Z","k":"t","ty":"testing","h":false,"ar":"Test shoot","z":"America/New_York","w":"Fri Dec 4, 12:00 PM ET"},{"i":"g90:akvile-kerpauskaite:TR-offer","a":"staff","o":"Troy","t":"Send travel and stay offer to Akvile Kerpauskaite and mother agency","d":"Itinerary: Paris Thu Jan 21 to Fri Jan 29 (Couture); Paris Fri Feb 26 to Wed Mar 10 (Women's). Estimated total $2,629 (flights $280, housing $1,100, meals and transport $770, transfers $240, visa and insurance $0, 10% contingency). Replace the estimate with real quotes first.","u":"2026-12-07T17:00:00Z","k":"t","ty":"visa_travel","h":true,"ar":"Travel","z":"America/New_York","w":"Mon Dec 7, 12:00 PM ET"},{"i":"g90:akvile-kerpauskaite:TS1","a":"model","o":"Akvile Kerpauskaite","t":"Test shoot 1: Akvile","d":"Call time 9:00 AM, wrap about 5:00 PM. Amsterdam studio. Bring a clean face, hair as discussed, and snacks.","u":"2026-12-08T08:00:00Z","k":"e","ty":"test","h":false,"ar":"Test shoot","z":"Europe/Paris","w":"Tue Dec 8, 9:00 AM Paris (Tue Dec 8 3:00 AM ET)","en":"2026-12-08T16:00:00Z","loc":"Amsterdam studio","ek":""},{"i":"g90:akvile-kerpauskaite:TS1-selects","a":"staff","o":"Erica","t":"Test shoot 1: send selects (Akvile)","d":"Send the first selects to the model and mother agency for approval.","u":"2026-12-10T22:00:00Z","k":"t","ty":"testing","h":false,"ar":"Test shoot","z":"America/New_York","w":"Thu Dec 10, 5:00 PM ET"},{"i":"g90:akvile-kerpauskaite:TR-approve","a":"model","o":"Akvile Kerpauskaite","t":"Approve your travel and stay plan: about $2,629","d":"Your season itinerary: Paris Thu Jan 21 to Fri Jan 29 (Couture); Paris Fri Feb 26 to Wed Mar 10 (Women's). Estimated total $2,629: flights $280, housing $1,100, meals and local transport $770, airport transfers $240, visa and insurance $0, contingency $239. This is an estimate until tickets are booked; final numbers are shown before anything is charged. Tap Complete to approve, or request a change with a note. Due Fri Dec 11, 5:00 PM Paris (Fri Dec 11 11:00 AM ET).","u":"2026-12-11T16:00:00Z","k":"t","ty":"visa_travel","h":true,"ar":"Travel","z":"Europe/Paris","w":"Fri Dec 11, 5:00 PM Paris (Fri Dec 11 11:00 AM ET)","amt":2629},{"i":"g90:akvile-kerpauskaite:TR-approve-e","a":"model","o":"Akvile Kerpauskaite","t":"Travel plan approval due","d":"Approve the travel and stay estimate (about $2,629).","u":"2026-12-11T16:00:00Z","k":"e","ty":"deadline","h":false,"ar":"Travel","z":"Europe/Paris","w":"Fri Dec 11, 5:00 PM Paris (Fri Dec 11 11:00 AM ET)","en":null,"loc":null,"ek":"travel"},{"i":"g90:akvile-kerpauskaite:PA4","a":"partner","o":"Mother agency","t":"Co-sign travel advance and recoup terms (Akvile Kerpauskaite)","d":"Estimated travel and stay about $2,629. Please confirm you accept the advance and how it is recouped.","u":"2026-12-11T17:00:00Z","k":"t","ty":"visa_travel","h":false,"ar":"Travel","z":"America/New_York","w":"Fri Dec 11, 12:00 PM ET"},{"i":"g90:akvile-kerpauskaite:SK2","a":"model","o":"Akvile Kerpauskaite","t":"Skin submission #2 (progress): photos due","d":"Skin submission = 4 photos in daylight by a window, no makeup, no filter, no retouching: front, left, right, and a close-up of any area you want help with. Add three lines: skin type as you see it, any concerns, and any product reaction. A licensed skin professional reviews it. You can choose to share only the photos and not any medical history. Due Mon Dec 14, 5:00 PM Paris (Mon Dec 14 11:00 AM ET).","u":"2026-12-14T16:00:00Z","k":"t","ty":"progress_submission","h":false,"ar":"Skin","z":"Europe/Paris","w":"Mon Dec 14, 5:00 PM Paris (Mon Dec 14 11:00 AM ET)"},{"i":"g90:akvile-kerpauskaite:SK2e","a":"model","o":"Akvile Kerpauskaite","t":"Skin submission #2 due","d":"Upload your skin photos in the portal today.","u":"2026-12-14T16:00:00Z","k":"e","ty":"deadline","h":false,"ar":"Skin","z":"Europe/Paris","w":"Mon Dec 14, 5:00 PM Paris (Mon Dec 14 11:00 AM ET)","en":null,"loc":null,"ek":"model meeting"},{"i":"g90:akvile-kerpauskaite:TS1-approve","a":"model","o":"Akvile Kerpauskaite","t":"Approve your test shoot 1 selects","d":"Pick your favorites and tell your agent what you do not want used. Tap Complete when done.","u":"2026-12-14T16:00:00Z","k":"t","ty":"testing","h":false,"ar":"Test shoot","z":"Europe/Paris","w":"Mon Dec 14, 5:00 PM Paris (Mon Dec 14 11:00 AM ET)"},{"i":"g90:akvile-kerpauskaite:WK2","a":"model","o":"Akvile Kerpauskaite","t":"Walk video #2: send your 20-second walk","d":"Walk practice, 30 minutes, Tuesday and Thursday. Warm up 5 minutes. Straight-line walk of 10 to 15 steps with level eyes and shoulders back, a clean turn at the end, pause, turn back. Practice in the shoe height you expect to wear. Film one 20-second clip from the front and one from the side, phone at hip height, plain background, full body in frame. Your agent gives written feedback and one drill for the next week. Due Mon Dec 14, 5:00 PM Paris (Mon Dec 14 11:00 AM ET).","u":"2026-12-14T16:00:00Z","k":"t","ty":"training","h":false,"ar":"Walk","z":"Europe/Paris","w":"Mon Dec 14, 5:00 PM Paris (Mon Dec 14 11:00 AM ET)"},{"i":"g90:akvile-kerpauskaite:WK2e","a":"model","o":"Akvile Kerpauskaite","t":"Walk practice video #2 due","d":"Send your walk video in the portal today.","u":"2026-12-14T16:00:00Z","k":"e","ty":"training","h":false,"ar":"Walk","z":"Europe/Paris","w":"Mon Dec 14, 5:00 PM Paris (Mon Dec 14 11:00 AM ET)","en":null,"loc":null,"ek":"walk practice"},{"i":"g90:akvile-kerpauskaite:TR-fund","a":"staff","o":"Sophia","t":"Release travel advance after approvals (Akvile Kerpauskaite)","d":"Only after the model and mother agency approve. Estimated $2,629.","u":"2026-12-14T17:00:00Z","k":"t","ty":"visa_travel","h":false,"ar":"Travel","z":"America/New_York","w":"Mon Dec 14, 12:00 PM ET"},{"i":"g90:akvile-kerpauskaite:TS1-papprove","a":"partner","o":"Mother agency","t":"Approve test shoot 1 selects (Akvile Kerpauskaite)","d":"Approve the selects or send notes so the retouch can start.","u":"2026-12-14T17:00:00Z","k":"t","ty":"testing","h":false,"ar":"Test shoot","z":"America/New_York","w":"Mon Dec 14, 12:00 PM ET"},{"i":"g90:akvile-kerpauskaite:TS1-retouch","a":"staff","o":"Erica","t":"Test shoot 1: retouched finals delivered (Akvile)","d":"Retouched finals saved to the model's media in the portal.","u":"2026-12-17T22:00:00Z","k":"t","ty":"testing","h":true,"ar":"Test shoot","z":"America/New_York","w":"Thu Dec 17, 5:00 PM ET"},{"i":"g90:akvile-kerpauskaite:H2","a":"model","o":"Akvile Kerpauskaite","t":"Physical exam and bloodwork: done and cleared","d":"Physical exam and bloodwork as your clinician advises (iron, vitamin D, B12 and thyroid are common for travel season), a dental cleaning and a vision check, all by the dates in your gameplan. You choose what to share: MDV only needs 'cleared' or 'not cleared', never your results. Travel health: ask your clinician about vaccines or medicines for your route, carry a copy of prescriptions, and bring your insurance card. Due Fri Dec 18, 5:00 PM Paris (Fri Dec 18 11:00 AM ET).","u":"2026-12-18T16:00:00Z","k":"t","ty":"progress_submission","h":true,"ar":"Health","z":"Europe/Paris","w":"Fri Dec 18, 5:00 PM Paris (Fri Dec 18 11:00 AM ET)"},{"i":"g90:akvile-kerpauskaite:H2e","a":"model","o":"Akvile Kerpauskaite","t":"Health layout due: physical, dental, vision","d":"Tell your agent you are cleared.","u":"2026-12-18T16:00:00Z","k":"e","ty":"deadline","h":false,"ar":"Health","z":"Europe/Paris","w":"Fri Dec 18, 5:00 PM Paris (Fri Dec 18 11:00 AM ET)","en":null,"loc":null,"ek":"model meeting"},{"i":"g90:akvile-kerpauskaite:H3","a":"model","o":"Akvile Kerpauskaite","t":"Dental cleaning and vision check: done","d":"Book both and tell your agent 'done'. Bring glasses or contact prescriptions if you use them.","u":"2026-12-18T16:00:00Z","k":"t","ty":"progress_submission","h":false,"ar":"Health","z":"Europe/Paris","w":"Fri Dec 18, 5:00 PM Paris (Fri Dec 18 11:00 AM ET)"},{"i":"g90:akvile-kerpauskaite:TR-tix","a":"staff","o":"Troy","t":"Tickets issued for Akvile Kerpauskaite","d":"Book flights only when the visa (if needed) is in the passport and the travel plan is approved. Send e-tickets to the model and mother agency.","u":"2026-12-18T17:00:00Z","k":"t","ty":"visa_travel","h":true,"ar":"Travel","z":"America/New_York","w":"Fri Dec 18, 12:00 PM ET"},{"i":"g90:akvile-kerpauskaite:TS1-package","a":"staff","o":"Erica","t":"Test shoot 1: add to book and push the package (Akvile)","d":"Add the images to the book and website, then send the package to clients and mother agencies.","u":"2026-12-21T22:00:00Z","k":"t","ty":"testing","h":true,"ar":"Test shoot","z":"America/New_York","w":"Mon Dec 21, 5:00 PM ET"},{"i":"g90:akvile-kerpauskaite:TS2-team","a":"staff","o":"Erica","t":"Test shoot 2: lock photographer, MUA, stylist and studio (Akvile)","d":"Shoot is Tue Jan 5, 2027, 9:00 AM Paris at Amsterdam studio. Book photographer, makeup, hair, stylist and studio, send the mood board to Akvile and the mother agency, and confirm wardrobe. HARD STOP: shoot cannot slip after this time.","u":"2026-12-22T17:00:00Z","k":"t","ty":"testing","h":true,"ar":"Test shoot","z":"America/New_York","w":"Tue Dec 22, 12:00 PM ET"},{"i":"g90:akvile-kerpauskaite:TS2-concept","a":"partner","o":"Mother agency","t":"Approve test shoot 2 concept (Akvile Kerpauskaite)","d":"Please approve or comment on the concept and looks for the test shoot on Tue Jan 5, 2027.","u":"2026-12-29T17:00:00Z","k":"t","ty":"testing","h":false,"ar":"Test shoot","z":"America/New_York","w":"Tue Dec 29, 12:00 PM ET"},{"i":"g90:akvile-kerpauskaite:TS2-confirm","a":"model","o":"Akvile Kerpauskaite","t":"Confirm your test shoot 2 call sheet","d":"Tap Complete when you have read the call sheet and confirm you can be there at 9:00 AM on Tue Jan 5, 2027. Skin prep: no new products, no waxing, sleep 8 hours.","u":"2026-12-30T16:00:00Z","k":"t","ty":"testing","h":false,"ar":"Test shoot","z":"Europe/Paris","w":"Wed Dec 30, 5:00 PM Paris (Wed Dec 30 11:00 AM ET)"},{"i":"g90:akvile-kerpauskaite:TS2-callsheet","a":"staff","o":"Erica","t":"Test shoot 2: send call sheet (Akvile)","d":"Call sheet to Akvile and mother agency: address, call time 9:00 AM Paris, wardrobe, skin prep and what to eat.","u":"2026-12-30T17:00:00Z","k":"t","ty":"testing","h":false,"ar":"Test shoot","z":"America/New_York","w":"Wed Dec 30, 12:00 PM ET"},{"i":"g90:akvile-kerpauskaite:TS2","a":"model","o":"Akvile Kerpauskaite","t":"Test shoot 2: Akvile","d":"Call time 9:00 AM, wrap about 5:00 PM. Amsterdam studio. Bring a clean face, hair as discussed, and snacks.","u":"2027-01-05T08:00:00Z","k":"e","ty":"test","h":false,"ar":"Test shoot","z":"Europe/Paris","w":"Tue Jan 5, 9:00 AM Paris (Tue Jan 5 3:00 AM ET)","en":"2027-01-05T16:00:00Z","loc":"Amsterdam studio","ek":""},{"i":"g90:akvile-kerpauskaite:CK1","a":"model","o":"Akvile Kerpauskaite","t":"Mid-season check-in call with your agent","d":"30 minutes: how you feel, sleep, food, skin, walk and travel. Bring questions.","u":"2027-01-06T16:00:00Z","k":"e","ty":"meeting","h":false,"ar":"Health","z":"Europe/Paris","w":"Wed Jan 6, 5:00 PM Paris (Wed Jan 6 11:00 AM ET)","en":"2027-01-06T16:30:00Z","loc":null,"ek":"model meeting"},{"i":"g90:akvile-kerpauskaite:TS2-selects","a":"staff","o":"Erica","t":"Test shoot 2: send selects (Akvile)","d":"Send the first selects to the model and mother agency for approval.","u":"2027-01-07T22:00:00Z","k":"t","ty":"testing","h":false,"ar":"Test shoot","z":"America/New_York","w":"Thu Jan 7, 5:00 PM ET"},{"i":"g90:akvile-kerpauskaite:SK3","a":"model","o":"Akvile Kerpauskaite","t":"Skin submission #3 (pre-show): photos due","d":"Skin submission = 4 photos in daylight by a window, no makeup, no filter, no retouching: front, left, right, and a close-up of any area you want help with. Add three lines: skin type as you see it, any concerns, and any product reaction. A licensed skin professional reviews it. You can choose to share only the photos and not any medical history. Due Mon Jan 11, 5:00 PM Paris (Mon Jan 11 11:00 AM ET).","u":"2027-01-11T16:00:00Z","k":"t","ty":"progress_submission","h":false,"ar":"Skin","z":"Europe/Paris","w":"Mon Jan 11, 5:00 PM Paris (Mon Jan 11 11:00 AM ET)"},{"i":"g90:akvile-kerpauskaite:SK3e","a":"model","o":"Akvile Kerpauskaite","t":"Skin submission #3 due","d":"Upload your skin photos in the portal today.","u":"2027-01-11T16:00:00Z","k":"e","ty":"deadline","h":false,"ar":"Skin","z":"Europe/Paris","w":"Mon Jan 11, 5:00 PM Paris (Mon Jan 11 11:00 AM ET)","en":null,"loc":null,"ek":"model meeting"},{"i":"g90:akvile-kerpauskaite:TS2-approve","a":"model","o":"Akvile Kerpauskaite","t":"Approve your test shoot 2 selects","d":"Pick your favorites and tell your agent what you do not want used. Tap Complete when done.","u":"2027-01-11T16:00:00Z","k":"t","ty":"testing","h":false,"ar":"Test shoot","z":"Europe/Paris","w":"Mon Jan 11, 5:00 PM Paris (Mon Jan 11 11:00 AM ET)"},{"i":"g90:akvile-kerpauskaite:WK3","a":"model","o":"Akvile Kerpauskaite","t":"Walk video #3: send your 20-second walk","d":"Walk practice, 30 minutes, Tuesday and Thursday. Warm up 5 minutes. Straight-line walk of 10 to 15 steps with level eyes and shoulders back, a clean turn at the end, pause, turn back. Practice in the shoe height you expect to wear. Film one 20-second clip from the front and one from the side, phone at hip height, plain background, full body in frame. Your agent gives written feedback and one drill for the next week. Due Mon Jan 11, 5:00 PM Paris (Mon Jan 11 11:00 AM ET).","u":"2027-01-11T16:00:00Z","k":"t","ty":"training","h":false,"ar":"Walk","z":"Europe/Paris","w":"Mon Jan 11, 5:00 PM Paris (Mon Jan 11 11:00 AM ET)"},{"i":"g90:akvile-kerpauskaite:WK3e","a":"model","o":"Akvile Kerpauskaite","t":"Walk practice video #3 due","d":"Send your walk video in the portal today.","u":"2027-01-11T16:00:00Z","k":"e","ty":"training","h":false,"ar":"Walk","z":"Europe/Paris","w":"Mon Jan 11, 5:00 PM Paris (Mon Jan 11 11:00 AM ET)","en":null,"loc":null,"ek":"walk practice"},{"i":"g90:akvile-kerpauskaite:TS2-papprove","a":"partner","o":"Mother agency","t":"Approve test shoot 2 selects (Akvile Kerpauskaite)","d":"Approve the selects or send notes so the retouch can start.","u":"2027-01-11T17:00:00Z","k":"t","ty":"testing","h":false,"ar":"Test shoot","z":"America/New_York","w":"Mon Jan 11, 12:00 PM ET"},{"i":"g90:akvile-kerpauskaite:TS2-retouch","a":"staff","o":"Erica","t":"Test shoot 2: retouched finals delivered (Akvile)","d":"Retouched finals saved to the model's media in the portal.","u":"2027-01-14T22:00:00Z","k":"t","ty":"testing","h":true,"ar":"Test shoot","z":"America/New_York","w":"Thu Jan 14, 5:00 PM ET"},{"i":"g90:akvile-kerpauskaite:PA6","a":"partner","o":"Mother agency","t":"Confirm arrival date and emergency contact (Akvile Kerpauskaite)","d":"Arrival Thu Jan 21, 2027. Confirm the contact and, for anyone under 18, the guardian.","u":"2027-01-15T17:00:00Z","k":"t","ty":"visa_travel","h":false,"ar":"Travel","z":"America/New_York","w":"Fri Jan 15, 12:00 PM ET"},{"i":"g90:akvile-kerpauskaite:TR-house","a":"staff","o":"Troy","t":"Housing confirmed and address sent (Akvile Kerpauskaite)","d":"Confirm the bed, key pickup and house rules and send them to the model and mother agency.","u":"2027-01-15T17:00:00Z","k":"t","ty":"visa_travel","h":false,"ar":"Travel","z":"America/New_York","w":"Fri Jan 15, 12:00 PM ET"},{"i":"g90:akvile-kerpauskaite:TR-ready","a":"model","o":"Akvile Kerpauskaite","t":"Pre-flight check: documents, health and packing","d":"Passport, visa, tickets, insurance card, prescriptions, charger, walking shoes and your skin kit. Confirm you are ready.","u":"2027-01-18T16:00:00Z","k":"t","ty":"visa_travel","h":false,"ar":"Travel","z":"Europe/Paris","w":"Mon Jan 18, 5:00 PM Paris (Mon Jan 18 11:00 AM ET)"},{"i":"g90:akvile-kerpauskaite:TS2-package","a":"staff","o":"Erica","t":"Test shoot 2: add to book and push the package (Akvile)","d":"Add the images to the book and website, then send the package to clients and mother agencies.","u":"2027-01-18T22:00:00Z","k":"t","ty":"testing","h":true,"ar":"Test shoot","z":"America/New_York","w":"Mon Jan 18, 5:00 PM ET"},{"i":"g90:akvile-kerpauskaite:TR-arr","a":"model","o":"Akvile Kerpauskaite","t":"Arrival: Akvile lands","d":"Landing in Paris. Airport pickup and address are in your gameplan.","u":"2027-01-21T11:00:00Z","k":"e","ty":"travel","h":false,"ar":"Travel","z":"Europe/Paris","w":"Thu Jan 21, 12:00 PM Paris (Thu Jan 21 6:00 AM ET)","en":null,"loc":"Paris","ek":"arrival"},{"i":"g90:akvile-kerpauskaite:WKOFF","a":"model","o":"Akvile Kerpauskaite","t":"Walk-off with your agent (Akvile)","d":"In-person walk check with your agent: straight walk, turns, pace and shoes. About 45 minutes.","u":"2027-01-22T09:00:00Z","k":"e","ty":"training","h":false,"ar":"Walk","z":"Europe/Paris","w":"Fri Jan 22, 10:00 AM Paris (Fri Jan 22 4:00 AM ET)","en":"2027-01-22T09:45:00Z","loc":"Paris","ek":"walk practice"},{"i":"g90:akvile-kerpauskaite:DG","a":"model","o":"Akvile Kerpauskaite","t":"Digitals session (Akvile)","d":"Fresh digitals for casting: clean face, fitted plain clothes, hair back, no jewelry. Front, profile, back, full length, smile and walk video.","u":"2027-01-22T10:00:00Z","k":"e","ty":"test","h":false,"ar":"Digitals","z":"Europe/Paris","w":"Fri Jan 22, 11:00 AM Paris (Fri Jan 22 5:00 AM ET)","en":"2027-01-22T12:00:00Z","loc":"Paris","ek":"digitals"},{"i":"g90:akvile-kerpauskaite:DGu","a":"staff","o":"Erica","t":"Digitals up and comp card updated (Akvile Kerpauskaite)","d":"Upload the digitals, update the comp card and measurements, and tell the mother agency.","u":"2027-01-26T22:00:00Z","k":"t","ty":"progress_submission","h":true,"ar":"Digitals","z":"America/New_York","w":"Tue Jan 26, 5:00 PM ET"},{"i":"g90:akvile-kerpauskaite:DGs","a":"staff","o":"Erica","t":"Digitals sent to mother agency and top clients (Akvile Kerpauskaite)","d":"Send the new digitals to the mother agency and the casting directors on this season's list.","u":"2027-01-27T22:00:00Z","k":"t","ty":"casting_show","h":false,"ar":"Digitals","z":"America/New_York","w":"Wed Jan 27, 5:00 PM ET"},{"i":"g90:akvile-kerpauskaite:SK4","a":"model","o":"Akvile Kerpauskaite","t":"Skin submission #4 (check): photos due","d":"Skin submission = 4 photos in daylight by a window, no makeup, no filter, no retouching: front, left, right, and a close-up of any area you want help with. Add three lines: skin type as you see it, any concerns, and any product reaction. A licensed skin professional reviews it. You can choose to share only the photos and not any medical history. Due Mon Feb 1, 5:00 PM Paris (Mon Feb 1 11:00 AM ET).","u":"2027-02-01T16:00:00Z","k":"t","ty":"progress_submission","h":false,"ar":"Skin","z":"Europe/Paris","w":"Mon Feb 1, 5:00 PM Paris (Mon Feb 1 11:00 AM ET)"},{"i":"g90:akvile-kerpauskaite:SK4e","a":"model","o":"Akvile Kerpauskaite","t":"Skin submission #4 due","d":"Upload your skin photos in the portal today.","u":"2027-02-01T16:00:00Z","k":"e","ty":"deadline","h":false,"ar":"Skin","z":"Europe/Paris","w":"Mon Feb 1, 5:00 PM Paris (Mon Feb 1 11:00 AM ET)","en":null,"loc":null,"ek":"model meeting"}]},{"name":"Clara Wahlqvist","gp":{"title":"90-Day Gameplan: Nov 8, 2026 to Feb 5, 2027","key_date":"2027-01-25","key_label":"Paris Haute Couture SS27","welcome":"Welcome to your 90-day gameplan, Clara. Every task has a date and a time in your own time zone. Tap Complete when a task is done, or request a new date with a note. Your agent is Emma.","positioning":"Runway: Paris Haute Couture SS27 (Mon Jan 25 to Thu Jan 28); New York Fashion Week (CFDA Feb 10-16; Bureau Feb 11-14) (Wed Feb 10 to Tue Feb 16); Paris Women's FW27-28 (Mon Mar 1 to Tue Mar 9).","market":"Base: Amsterdam. Shows: Paris Haute Couture SS27, New York Fashion Week (CFDA Feb 10-16; Bureau Feb 11-14), Paris Women's FW27-28.","image_rules":"Test shoots: 2 in this block. Fresh digitals close to your first show. Skin photos four times (Nov 16, Dec 14, pre-show, Feb 1). Nothing is posted or sent without your approval of the selects.","risks":"US work visa must be in the passport by Jan 22 for NYFW. Legal fee is quoted separately. USA O-1 visa being finalized.","cadence":{"daily":"Skin routine morning and night, food and water, sleep 8 hours","walk":"Tuesday and Thursday 30 minutes","weekly":"Sunday wellness check-in with your agent","deadlines":"All dates and times are in your gameplan tasks"}},"ds":{"built":"2026-11-08","until":"2027-02-05","blocks":[{"id":"gp_snack1","days":["0","1","2","3","4","5","6"],"start":"10:30","end":"10:45","title":"Snack + water (fueling plan)","cat":"meal","until":"2027-02-05"},{"id":"gp_snack2","days":["0","1","2","3","4","5","6"],"start":"15:30","end":"15:45","title":"Snack + water (fueling plan)","cat":"meal","until":"2027-02-05"},{"id":"gp_walk","days":["2","4"],"start":"18:00","end":"18:30","title":"Walk practice (gameplan)","cat":"model","until":"2027-02-05"},{"id":"gp_checkin","days":["0"],"start":"17:00","end":"17:20","title":"Sunday wellness check-in with your agent","cat":"routine","until":"2027-02-05"}],"habits":[{"id":"gp_skin","label":"Skin plan from your gameplan: morning and night"},{"id":"gp_fuel","label":"Fueling plan: protein at every meal, two snacks, water"},{"id":"gp_walk","label":"Walk practice Tuesday and Thursday"},{"id":"gp_sleep","label":"Sleep 8 hours"}],"weekly":[{"k":"gp_dates","t":"Open your gameplan: skin photos, walk videos, health checks and test shoots each have a set date and time"},{"k":"gp_walkvid","t":"Walk video due dates: Nov 23, Dec 14 and your pre-show date"}]},"items":[{"i":"g90:clara-wahlqvist:PLAN","a":"staff","o":"Emma","t":"Gameplan live for Clara Wahlqvist","d":"Check that the model sees the gameplan, the mother agency has partner tasks, and the DaySilk events appear.","u":"2026-11-10T17:00:00Z","k":"t","ty":"agent","h":true,"ar":"Gameplan","z":"America/New_York","w":"Tue Nov 10, 12:00 PM ET"},{"i":"g90:clara-wahlqvist:G1","a":"model","o":"Clara Wahlqvist","t":"Confirm your gameplan and shows","d":"Open your gameplan, read the dates, and tap Complete to confirm. Shows: Paris Haute Couture SS27, New York Fashion Week (CFDA Feb 10-16; Bureau Feb 11-14), Paris Women's FW27-28.","u":"2026-11-13T16:00:00Z","k":"t","ty":"agent","h":false,"ar":"Gameplan","z":"Europe/Paris","w":"Fri Nov 13, 5:00 PM Paris (Fri Nov 13 11:00 AM ET)"},{"i":"g90:clara-wahlqvist:V1","a":"model","o":"Clara Wahlqvist","t":"Passport check and evidence pack","d":"Passport valid 6+ months after return. Send press, past work and references your attorney asked for.","u":"2026-11-13T16:00:00Z","k":"t","ty":"visa_travel","h":true,"ar":"Visa","z":"Europe/Paris","w":"Fri Nov 13, 5:00 PM Paris (Fri Nov 13 11:00 AM ET)"},{"i":"g90:clara-wahlqvist:V2","a":"staff","o":"Sophia","t":"US counsel engaged and retainer paid (Clara Wahlqvist)","d":"Engage the immigration attorney and agree the fee. The legal fee is quoted separately and is not part of the model's travel amount.","u":"2026-11-13T17:00:00Z","k":"t","ty":"visa_travel","h":true,"ar":"Visa","z":"America/New_York","w":"Fri Nov 13, 12:00 PM ET"},{"i":"g90:clara-wahlqvist:SK1","a":"model","o":"Clara Wahlqvist","t":"Skin submission #1 (baseline): photos due","d":"Skin submission = 4 photos in daylight by a window, no makeup, no filter, no retouching: front, left, right, and a close-up of any area you want help with. Add three lines: skin type as you see it, any concerns, and any product reaction. A licensed skin professional reviews it. You can choose to share only the photos and not any medical history. Due Mon Nov 16, 5:00 PM Paris (Mon Nov 16 11:00 AM ET).","u":"2026-11-16T16:00:00Z","k":"t","ty":"progress_submission","h":false,"ar":"Skin","z":"Europe/Paris","w":"Mon Nov 16, 5:00 PM Paris (Mon Nov 16 11:00 AM ET)"},{"i":"g90:clara-wahlqvist:SK1e","a":"model","o":"Clara Wahlqvist","t":"Skin submission #1 due","d":"Upload your skin photos in the portal today.","u":"2026-11-16T16:00:00Z","k":"e","ty":"deadline","h":false,"ar":"Skin","z":"Europe/Paris","w":"Mon Nov 16, 5:00 PM Paris (Mon Nov 16 11:00 AM ET)","en":null,"loc":null,"ek":"model meeting"},{"i":"g90:clara-wahlqvist:PA1","a":"partner","o":"Mother agency","t":"Confirm representation and show list (Clara Wahlqvist)","d":"Confirm who represents the model for each market and which shows are approved.","u":"2026-11-18T17:00:00Z","k":"t","ty":"agent","h":false,"ar":"Gameplan","z":"America/New_York","w":"Wed Nov 18, 12:00 PM ET"},{"i":"g90:clara-wahlqvist:H1","a":"model","o":"Clara Wahlqvist","t":"Health intake: allergies, food limits, injuries","d":"Fill in the short intake form: allergies, food limits, injuries and anything you want us to plan around. You choose what to share. We never ask for weight or body-measurement targets.","u":"2026-11-20T16:00:00Z","k":"t","ty":"progress_submission","h":false,"ar":"Health","z":"Europe/Paris","w":"Fri Nov 20, 5:00 PM Paris (Fri Nov 20 11:00 AM ET)"},{"i":"g90:clara-wahlqvist:V3","a":"staff","o":"Troy","t":"US work visa O-1 petition (Clara Wahlqvist)","d":"Petition or application filed with counsel; save the receipt number in the portal.","u":"2026-11-20T17:00:00Z","k":"t","ty":"visa_travel","h":true,"ar":"Visa","z":"America/New_York","w":"Fri Nov 20, 12:00 PM ET"},{"i":"g90:clara-wahlqvist:SKP","a":"model","o":"Clara Wahlqvist","t":"Start your skin plan: read and confirm","d":"Every day: AM gentle cleanser, moisturizer, broad-spectrum SPF 30+. PM: remove sunscreen and makeup fully (double cleanse on shoot days), then moisturizer. Once a week: one gentle exfoliation and one hydrating mask. Patch-test anything new on the jaw for 3 days. Never sleep in makeup. If you shave, use a clean blade, shave with the grain and finish with an alcohol-free soother. Climate: cool, damp winter and indoor heating. Use a ceramide cream at night, run a humidifier where you sleep, and keep SPF on even when it is cloudy. Pre-show protocol (starts 14 days before your first show): no new active products, no peels, lasers, waxing or fillers in the last 7 days, no sunburn or tanning, sleep 8 hours, and remove all makeup at the end of every day. If anything flares, tell your agent the same day. Travel days: cleanse, put on a thick moisturizer, no new products, drink water through the flight, and use a hydrating mask after landing. Skin submission = 4 photos in daylight by a window, no makeup, no filter, no retouching: front, left, right, and a close-up of any area you want help with. Add three lines: skin type as you see it, any concerns, and any product reaction. A licensed skin professional reviews it. You can choose to share only the photos and not any medical history.","u":"2026-11-23T16:00:00Z","k":"t","ty":"progress_submission","h":false,"ar":"Skin","z":"Europe/Paris","w":"Mon Nov 23, 5:00 PM Paris (Mon Nov 23 11:00 AM ET)"},{"i":"g90:clara-wahlqvist:WK1","a":"model","o":"Clara Wahlqvist","t":"Walk video #1: send your 20-second walk","d":"Walk practice, 30 minutes, Tuesday and Thursday. Warm up 5 minutes. Straight-line walk of 10 to 15 steps with level eyes and shoulders back, a clean turn at the end, pause, turn back. Practice in the shoe height you expect to wear. Film one 20-second clip from the front and one from the side, phone at hip height, plain background, full body in frame. Your agent gives written feedback and one drill for the next week. Due Mon Nov 23, 5:00 PM Paris (Mon Nov 23 11:00 AM ET).","u":"2026-11-23T16:00:00Z","k":"t","ty":"training","h":false,"ar":"Walk","z":"Europe/Paris","w":"Mon Nov 23, 5:00 PM Paris (Mon Nov 23 11:00 AM ET)"},{"i":"g90:clara-wahlqvist:WK1e","a":"model","o":"Clara Wahlqvist","t":"Walk practice video #1 due","d":"Send your walk video in the portal today.","u":"2026-11-23T16:00:00Z","k":"e","ty":"training","h":false,"ar":"Walk","z":"Europe/Paris","w":"Mon Nov 23, 5:00 PM Paris (Mon Nov 23 11:00 AM ET)","en":null,"loc":null,"ek":"walk practice"},{"i":"g90:clara-wahlqvist:FUEL","a":"model","o":"Clara Wahlqvist","t":"Your fueling plan: read it and send allergies or food limits","d":"This is healthy fueling, not dieting. Three meals and two snacks a day, protein at every meal, a vegetable or fruit at most meals, whole grains or starch for energy on training and walk-practice days, and 2 to 3 liters of water. No crash dieting, cleanses, diet pills or skipped meals. MDV does not set weight or measurement targets for any model. If a doctor or dietitian gives you a plan, that plan wins. Tell us any allergies or food limits in your health intake so this plan fits you. Easy picks: eggs, yogurt or skyr, oats, fish, lentil or bean soups, whole-grain bread, roasted vegetables and fruit. In Paris, bakeries and markets make it simple to pair a protein with a fruit or vegetable. Show weeks: carry snacks (nuts, fruit, a protein bar, a sandwich), eat before every call time, keep water with you, and keep caffeine and alcohol low the night before a casting or show.","u":"2026-11-25T16:00:00Z","k":"t","ty":"training","h":false,"ar":"Diet","z":"Europe/Paris","w":"Wed Nov 25, 5:00 PM Paris (Wed Nov 25 11:00 AM ET)"},{"i":"g90:clara-wahlqvist:PA3","a":"partner","o":"Mother agency","t":"Sign off the gameplan and test shoot plan (Clara Wahlqvist)","d":"Review the gameplan, test shoot dates and image rules, then approve or comment.","u":"2026-11-25T17:00:00Z","k":"t","ty":"agent","h":false,"ar":"Gameplan","z":"America/New_York","w":"Wed Nov 25, 12:00 PM ET"},{"i":"g90:clara-wahlqvist:TS1-team","a":"staff","o":"Emma","t":"Test shoot 1: lock photographer, MUA, stylist and studio (Clara)","d":"Shoot is Wed Dec 9, 2026, 9:00 AM Paris at Amsterdam studio. Book photographer, makeup, hair, stylist and studio, send the mood board to Clara and the mother agency, and confirm wardrobe. HARD STOP: shoot cannot slip after this time.","u":"2026-11-25T17:00:00Z","k":"t","ty":"testing","h":true,"ar":"Test shoot","z":"America/New_York","w":"Wed Nov 25, 12:00 PM ET"},{"i":"g90:clara-wahlqvist:TS1-concept","a":"partner","o":"Mother agency","t":"Approve test shoot 1 concept (Clara Wahlqvist)","d":"Please approve or comment on the concept and looks for the test shoot on Wed Dec 9, 2026.","u":"2026-12-02T17:00:00Z","k":"t","ty":"testing","h":false,"ar":"Test shoot","z":"America/New_York","w":"Wed Dec 2, 12:00 PM ET"},{"i":"g90:clara-wahlqvist:TS1-callsheet","a":"staff","o":"Emma","t":"Test shoot 1: send call sheet (Clara)","d":"Call sheet to Clara and mother agency: address, call time 9:00 AM Paris, wardrobe, skin prep and what to eat.","u":"2026-12-04T17:00:00Z","k":"t","ty":"testing","h":false,"ar":"Test shoot","z":"America/New_York","w":"Fri Dec 4, 12:00 PM ET"},{"i":"g90:clara-wahlqvist:TS1-confirm","a":"model","o":"Clara Wahlqvist","t":"Confirm your test shoot 1 call sheet","d":"Tap Complete when you have read the call sheet and confirm you can be there at 9:00 AM on Wed Dec 9, 2026. Skin prep: no new products, no waxing, sleep 8 hours.","u":"2026-12-07T16:00:00Z","k":"t","ty":"testing","h":false,"ar":"Test shoot","z":"Europe/Paris","w":"Mon Dec 7, 5:00 PM Paris (Mon Dec 7 11:00 AM ET)"},{"i":"g90:clara-wahlqvist:TR-offer","a":"staff","o":"Troy","t":"Send travel and stay offer to Clara Wahlqvist and mother agency","d":"Itinerary: Paris Thu Jan 21 to Fri Jan 29 (Couture); New York Thu Feb 4 to Wed Feb 17 (NYFW (O-1)); Paris Fri Feb 26 to Wed Mar 10 (Women's). Estimated total $5,225 (flights $980, housing $2,010, meals a