r times (Nov 16, Dec 14, pre-show, Feb 1). Nothing is posted or sent without your approval of the selects.","risks":"Schengen visa must be filed by Nov 13 and decided by Dec 21. No decision means a same-day fallback plan. May sign in Milan. Decision Dec 4 changes the visa country and adds a Milan leg (Jan 15 to 19).","cadence":{"daily":"Skin routine morning and night, food and water, sleep 8 hours","walk":"Tuesday and Thursday 30 minutes","weekly":"Sunday wellness check-in with your agent","deadlines":"All dates and times are in your gameplan tasks"}},"ds":{"built":"2026-11-08","until":"2027-02-05","blocks":[{"id":"gp_snack1","days":["0","1","2","3","4","5","6"],"start":"10:30","end":"10:45","title":"Snack + water (fueling plan)","cat":"meal","until":"2027-02-05"},{"id":"gp_snack2","days":["0","1","2","3","4","5","6"],"start":"15:30","end":"15:45","title":"Snack + water (fueling plan)","cat":"meal","until":"2027-02-05"},{"id":"gp_walk","days":["2","4"],"start":"18:00","end":"18:30","title":"Walk practice (gameplan)","cat":"model","until":"2027-02-05"},{"id":"gp_checkin","days":["0"],"start":"17:00","end":"17:20","title":"Sunday wellness check-in with your agent","cat":"routine","until":"2027-02-05"}],"habits":[{"id":"gp_skin","label":"Skin plan from your gameplan: morning and night"},{"id":"gp_fuel","label":"Fueling plan: protein at every meal, two snacks, water"},{"id":"gp_walk","label":"Walk practice Tuesday and Thursday"},{"id":"gp_sleep","label":"Sleep 8 hours"}],"weekly":[{"k":"gp_dates","t":"Open your gameplan: skin photos, walk videos, health checks and test shoots each have a set date and time"},{"k":"gp_walkvid","t":"Walk video due dates: Nov 23, Dec 14 and your pre-show date"}]},"items":[{"i":"g90:zainab-adetayo:V1","a":"model","o":"Zainab Adetayo","t":"Passport check and scans","d":"Passport valid at least 6 months after your return with 2 blank pages. Upload a clear scan today.","u":"2026-11-10T16:00:00Z","k":"t","ty":"visa_travel","h":true,"ar":"Visa","z":"Africa/Lagos","w":"Tue Nov 10, 5:00 PM Lagos (Tue Nov 10 11:00 AM ET)"},{"i":"g90:zainab-adetayo:PLAN","a":"staff","o":"Erica","t":"Gameplan live for Zainab Adetayo","d":"Check that the model sees the gameplan, the mother agency has partner tasks, and the DaySilk events appear.","u":"2026-11-10T17:00:00Z","k":"t","ty":"agent","h":true,"ar":"Gameplan","z":"America/New_York","w":"Tue Nov 10, 12:00 PM ET"},{"i":"g90:zainab-adetayo:PA2","a":"partner","o":"Mother agency","t":"Send visa support documents (Zainab Adetayo)","d":"Invitation or agency letter and any contract pages needed for the Schengen application.","u":"2026-11-11T17:00:00Z","k":"t","ty":"visa_travel","h":true,"ar":"Visa","z":"America/New_York","w":"Wed Nov 11, 12:00 PM ET"},{"i":"g90:zainab-adetayo:V2","a":"staff","o":"Troy","t":"Visa pack complete for Zainab Adetayo","d":"Support letter, accommodation proof, travel insurance, finances, flight reservation, photos.","u":"2026-11-11T17:00:00Z","k":"t","ty":"visa_travel","h":true,"ar":"Visa","z":"America/New_York","w":"Wed Nov 11, 12:00 PM ET"},{"i":"g90:zainab-adetayo:V3e","a":"model","o":"Zainab Adetayo","t":"Visa filing day","d":"Visa application and biometrics.","u":"2026-11-13T09:00:00Z","k":"e","ty":"visa","h":false,"ar":"Visa","z":"Africa/Lagos","w":"Fri Nov 13, 10:00 AM Lagos (Fri Nov 13 4:00 AM ET)","en":"2026-11-13T11:00:00Z","loc":null,"ek":"visa appointment"},{"i":"g90:zainab-adetayo:G1","a":"model","o":"Zainab Adetayo","t":"Confirm your gameplan and shows","d":"Open your gameplan, read the dates, and tap Complete to confirm. Shows: Paris Men's FW27-28, Paris Haute Couture SS27, Paris Women's FW27-28.","u":"2026-11-13T16:00:00Z","k":"t","ty":"agent","h":false,"ar":"Gameplan","z":"Africa/Lagos","w":"Fri Nov 13, 5:00 PM Lagos (Fri Nov 13 11:00 AM ET)"},{"i":"g90:zainab-adetayo:V3","a":"model","o":"Zainab Adetayo","t":"Visa application filed and biometrics done","d":"Attend your visa centre appointment with every document. Tell your agent the moment it is done.","u":"2026-11-13T16:00:00Z","k":"t","ty":"visa_travel","h":true,"ar":"Visa","z":"Africa/Lagos","w":"Fri Nov 13, 5:00 PM Lagos (Fri Nov 13 11:00 AM ET)"},{"i":"g90:zainab-adetayo:SK1","a":"model","o":"Zainab Adetayo","t":"Skin submission #1 (baseline): photos due","d":"Skin submission = 4 photos in daylight by a window, no makeup, no filter, no retouching: front, left, right, and a close-up of any area you want help with. Add three lines: skin type as you see it, any concerns, and any product reaction. A licensed skin professional reviews it. You can choose to share only the photos and not any medical history. Due Mon Nov 16, 5:00 PM Lagos (Mon Nov 16 11:00 AM ET).","u":"2026-11-16T16:00:00Z","k":"t","ty":"progress_submission","h":false,"ar":"Skin","z":"Africa/Lagos","w":"Mon Nov 16, 5:00 PM Lagos (Mon Nov 16 11:00 AM ET)"},{"i":"g90:zainab-adetayo:SK1e","a":"model","o":"Zainab Adetayo","t":"Skin submission #1 due","d":"Upload your skin photos in the portal today.","u":"2026-11-16T16:00:00Z","k":"e","ty":"deadline","h":false,"ar":"Skin","z":"Africa/Lagos","w":"Mon Nov 16, 5:00 PM Lagos (Mon Nov 16 11:00 AM ET)","en":null,"loc":null,"ek":"model meeting"},{"i":"g90:zainab-adetayo:PA1","a":"partner","o":"Mother agency","t":"Confirm representation and show list (Zainab Adetayo)","d":"Confirm who represents the model for each market and which shows are approved. If the model is signing in Milan, tell us by Dec 4.","u":"2026-11-18T17:00:00Z","k":"t","ty":"agent","h":false,"ar":"Gameplan","z":"America/New_York","w":"Wed Nov 18, 12:00 PM ET"},{"i":"g90:zainab-adetayo:H1","a":"model","o":"Zainab Adetayo","t":"Health intake: allergies, food limits, injuries","d":"Fill in the short intake form: allergies, food limits, injuries and anything you want us to plan around. You choose what to share. We never ask for weight or body-measurement targets.","u":"2026-11-20T16:00:00Z","k":"t","ty":"progress_submission","h":false,"ar":"Health","z":"Africa/Lagos","w":"Fri Nov 20, 5:00 PM Lagos (Fri Nov 20 11:00 AM ET)"},{"i":"g90:zainab-adetayo:TS1-team","a":"staff","o":"Erica","t":"Test shoot 1: lock photographer, MUA, stylist and studio (Zainab)","d":"Shoot is Fri Dec 4, 2026, 9:00 AM Lagos at Lagos studio. Book photographer, makeup, hair, stylist and studio, send the mood board to Zainab and the mother agency, and confirm wardrobe. HARD STOP: shoot cannot slip after this time.","u":"2026-11-20T17:00:00Z","k":"t","ty":"testing","h":true,"ar":"Test shoot","z":"America/New_York","w":"Fri Nov 20, 12:00 PM ET"},{"i":"g90:zainab-adetayo:SKP","a":"model","o":"Zainab Adetayo","t":"Start your skin plan: read and confirm","d":"Every day: AM gentle cleanser, moisturizer, broad-spectrum SPF 30+. PM: remove sunscreen and makeup fully (double cleanse on shoot days), then moisturizer. Once a week: one gentle exfoliation and one hydrating mask. Patch-test anything new on the jaw for 3 days. Never sleep in makeup. If you shave, use a clean blade, shave with the grain and finish with an alcohol-free soother. Climate: heat and humidity. Use a gel or light lotion moisturizer. For breakouts or dark marks after breakouts, ask the reviewer about niacinamide in the morning and azelaic acid at night. Reapply SPF every 2 to 3 hours outdoors and rinse sweat off before it dries. Pre-show protocol (starts 14 days before your first show): no new active products, no peels, lasers, waxing or fillers in the last 7 days, no sunburn or tanning, sleep 8 hours, and remove all makeup at the end of every day. If anything flares, tell your agent the same day. Travel days: cleanse, put on a thick moisturizer, no new products, drink water through the flight, and use a hydrating mask after landing. Skin submission = 4 photos in daylight by a window, no makeup, no filter, no retouching: front, left, right, and a close-up of any area you want help with. Add three lines: skin type as you see it, any concerns, and any product reaction. A licensed skin professional reviews it. You can choose to share only the photos and not any medical history.","u":"2026-11-23T16:00:00Z","k":"t","ty":"progress_submission","h":false,"ar":"Skin","z":"Africa/Lagos","w":"Mon Nov 23, 5:00 PM Lagos (Mon Nov 23 11:00 AM ET)"},{"i":"g90:zainab-adetayo:WK1","a":"model","o":"Zainab Adetayo","t":"Walk video #1: send your 20-second walk","d":"Walk practice, 30 minutes, Tuesday and Thursday. Warm up 5 minutes. Straight-line walk of 10 to 15 steps with level eyes and shoulders back, a clean turn at the end, pause, turn back. Practice in the shoe height you expect to wear. Film one 20-second clip from the front and one from the side, phone at hip height, plain background, full body in frame. Your agent gives written feedback and one drill for the next week. Due Mon Nov 23, 5:00 PM Lagos (Mon Nov 23 11:00 AM ET).","u":"2026-11-23T16:00:00Z","k":"t","ty":"training","h":false,"ar":"Walk","z":"Africa/Lagos","w":"Mon Nov 23, 5:00 PM Lagos (Mon Nov 23 11:00 AM ET)"},{"i":"g90:zainab-adetayo:WK1e","a":"model","o":"Zainab Adetayo","t":"Walk practice video #1 due","d":"Send your walk video in the portal today.","u":"2026-11-23T16:00:00Z","k":"e","ty":"training","h":false,"ar":"Walk","z":"Africa/Lagos","w":"Mon Nov 23, 5:00 PM Lagos (Mon Nov 23 11:00 AM ET)","en":null,"loc":null,"ek":"walk practice"},{"i":"g90:zainab-adetayo:FUEL","a":"model","o":"Zainab Adetayo","t":"Your fueling plan: read it and send allergies or food limits","d":"This is healthy fueling, not dieting. Three meals and two snacks a day, protein at every meal, a vegetable or fruit at most meals, whole grains or starch for energy on training and walk-practice days, and 2 to 3 liters of water. No crash dieting, cleanses, diet pills or skipped meals. MDV does not set weight or measurement targets for any model. If a doctor or dietitian gives you a plan, that plan wins. Tell us any allergies or food limits in your health intake so this plan fits you. Easy local picks: grilled or steamed fish or chicken, beans or moi moi, efo riro or ugu with less oil, boiled or grilled plantain, ofada or brown rice, and fruit like pawpaw, oranges and watermelon. Jollof and fried snacks are fine in smaller portions with a protein beside them. Show weeks: carry snacks (nuts, fruit, a protein bar, a sandwich), eat before every call time, keep water with you, and keep caffeine and alcohol low the night before a casting or show.","u":"2026-11-25T16:00:00Z","k":"t","ty":"training","h":false,"ar":"Diet","z":"Africa/Lagos","w":"Wed Nov 25, 5:00 PM Lagos (Wed Nov 25 11:00 AM ET)"},{"i":"g90:zainab-adetayo:PA3","a":"partner","o":"Mother agency","t":"Sign off the gameplan and test shoot plan (Zainab Adetayo)","d":"Review the gameplan, test shoot dates and image rules, then approve or comment.","u":"2026-11-25T17:00:00Z","k":"t","ty":"agent","h":false,"ar":"Gameplan","z":"America/New_York","w":"Wed Nov 25, 12:00 PM ET"},{"i":"g90:zainab-adetayo:TS1-concept","a":"partner","o":"Mother agency","t":"Approve test shoot 1 concept (Zainab Adetayo)","d":"Please approve or comment on the concept and looks for the test shoot on Fri Dec 4, 2026.","u":"2026-11-27T17:00:00Z","k":"t","ty":"testing","h":false,"ar":"Test shoot","z":"America/New_York","w":"Fri Nov 27, 12:00 PM ET"},{"i":"g90:zainab-adetayo:TS2-team","a":"staff","o":"Erica","t":"Test shoot 2: lock photographer, MUA, stylist and studio (Zainab)","d":"Shoot is Mon Dec 14, 2026, 9:00 AM Lagos at Lagos studio. Book photographer, makeup, hair, stylist and studio, send the mood board to Zainab and the mother agency, and confirm wardrobe. HARD STOP: shoot cannot slip after this time.","u":"2026-11-30T17:00:00Z","k":"t","ty":"testing","h":true,"ar":"Test shoot","z":"America/New_York","w":"Mon Nov 30, 12:00 PM ET"},{"i":"g90:zainab-adetayo:TS1-callsheet","a":"staff","o":"Erica","t":"Test shoot 1: send call sheet (Zainab)","d":"Call sheet to Zainab and mother agency: address, call time 9:00 AM Lagos, wardrobe, skin prep and what to eat.","u":"2026-12-01T17:00:00Z","k":"t","ty":"testing","h":false,"ar":"Test shoot","z":"America/New_York","w":"Tue Dec 1, 12:00 PM ET"},{"i":"g90:zainab-adetayo:V4","a":"staff","o":"Troy","t":"Visa status check #1 (Zainab Adetayo)","d":"Check the tracking. If the case is stuck, escalate to Demontez.","u":"2026-12-01T17:00:00Z","k":"t","ty":"visa_travel","h":false,"ar":"Visa","z":"America/New_York","w":"Tue Dec 1, 12:00 PM ET"},{"i":"g90:zainab-adetayo:TS1-confirm","a":"model","o":"Zainab Adetayo","t":"Confirm your test shoot 1 call sheet","d":"Tap Complete when you have read the call sheet and confirm you can be there at 9:00 AM on Fri Dec 4, 2026. Skin prep: no new products, no waxing, sleep 8 hours.","u":"2026-12-02T16:00:00Z","k":"t","ty":"testing","h":false,"ar":"Test shoot","z":"Africa/Lagos","w":"Wed Dec 2, 5:00 PM Lagos (Wed Dec 2 11:00 AM ET)"},{"i":"g90:zainab-adetayo:TS1","a":"model","o":"Zainab Adetayo","t":"Test shoot 1: Zainab","d":"Call time 9:00 AM, wrap about 5:00 PM. Lagos studio. Bring a clean face, hair as discussed, and snacks.","u":"2026-12-04T08:00:00Z","k":"e","ty":"test","h":false,"ar":"Test shoot","z":"Africa/Lagos","w":"Fri Dec 4, 9:00 AM Lagos (Fri Dec 4 3:00 AM ET)","en":"2026-12-04T16:00:00Z","loc":"Lagos studio","ek":""},{"i":"g90:zainab-adetayo:TR-offer","a":"staff","o":"Troy","t":"Send travel and stay offer to Zainab Adetayo and mother agency","d":"Itinerary: Paris Sun Jan 10 to Mon Mar 15 (Paris Men's, Couture and Women's on one visa). Estimated total $8,019 (flights $1,150, housing $3,520, meals and transport $2,275, transfers $120, visa and insurance $225, 10% contingency). Replace the estimate with real quotes first.","u":"2026-12-07T17:00:00Z","k":"t","ty":"visa_travel","h":true,"ar":"Travel","z":"America/New_York","w":"Mon Dec 7, 12:00 PM ET"},{"i":"g90:zainab-adetayo:TS2-concept","a":"partner","o":"Mother agency","t":"Approve test shoot 2 concept (Zainab Adetayo)","d":"Please approve or comment on the concept and looks for the test shoot on Mon Dec 14, 2026.","u":"2026-12-07T17:00:00Z","k":"t","ty":"testing","h":false,"ar":"Test shoot","z":"America/New_York","w":"Mon Dec 7, 12:00 PM ET"},{"i":"g90:zainab-adetayo:TS1-selects","a":"staff","o":"Erica","t":"Test shoot 1: send selects (Zainab)","d":"Send the first selects to the model and mother agency for approval.","u":"2026-12-08T22:00:00Z","k":"t","ty":"testing","h":false,"ar":"Test shoot","z":"America/New_York","w":"Tue Dec 8, 5:00 PM ET"},{"i":"g90:zainab-adetayo:TS1-approve","a":"model","o":"Zainab Adetayo","t":"Approve your test shoot 1 selects","d":"Pick your favorites and tell your agent what you do not want used. Tap Complete when done.","u":"2026-12-10T16:00:00Z","k":"t","ty":"testing","h":false,"ar":"Test shoot","z":"Africa/Lagos","w":"Thu Dec 10, 5:00 PM Lagos (Thu Dec 10 11:00 AM ET)"},{"i":"g90:zainab-adetayo:TS1-papprove","a":"partner","o":"Mother agency","t":"Approve test shoot 1 selects (Zainab Adetayo)","d":"Approve the selects or send notes so the retouch can start.","u":"2026-12-10T17:00:00Z","k":"t","ty":"testing","h":false,"ar":"Test shoot","z":"America/New_York","w":"Thu Dec 10, 12:00 PM ET"},{"i":"g90:zainab-adetayo:TR-approve","a":"model","o":"Zainab Adetayo","t":"Approve your travel and stay plan: about $8,019","d":"Your season itinerary: Paris Sun Jan 10 to Mon Mar 15 (Paris Men's, Couture and Women's on one visa). Estimated total $8,019: flights $1,150, housing $3,520, meals and local transport $2,275, airport transfers $120, visa and insurance $225, contingency $729. This is an estimate until tickets are booked; final numbers are shown before anything is charged. Tap Complete to approve, or request a change with a note. Due Fri Dec 11, 5:00 PM Lagos (Fri Dec 11 11:00 AM ET).","u":"2026-12-11T16:00:00Z","k":"t","ty":"visa_travel","h":true,"ar":"Travel","z":"Africa/Lagos","w":"Fri Dec 11, 5:00 PM Lagos (Fri Dec 11 11:00 AM ET)","amt":8019},{"i":"g90:zainab-adetayo:TR-approve-e","a":"model","o":"Zainab Adetayo","t":"Travel plan approval due","d":"Approve the travel and stay estimate (about $8,019).","u":"2026-12-11T16:00:00Z","k":"e","ty":"deadline","h":false,"ar":"Travel","z":"Africa/Lagos","w":"Fri Dec 11, 5:00 PM Lagos (Fri Dec 11 11:00 AM ET)","en":null,"loc":null,"ek":"travel"},{"i":"g90:zainab-adetayo:TS2-confirm","a":"model","o":"Zainab Adetayo","t":"Confirm your test shoot 2 call sheet","d":"Tap Complete when you have read the call sheet and confirm you can be there at 9:00 AM on Mon Dec 14, 2026. Skin prep: no new products, no waxing, sleep 8 hours.","u":"2026-12-11T16:00:00Z","k":"t","ty":"testing","h":false,"ar":"Test shoot","z":"Africa/Lagos","w":"Fri Dec 11, 5:00 PM Lagos (Fri Dec 11 11:00 AM ET)"},{"i":"g90:zainab-adetayo:PA4","a":"partner","o":"Mother agency","t":"Co-sign travel advance and recoup terms (Zainab Adetayo)","d":"Estimated travel and stay about $8,019. Please confirm you accept the advance and how it is recouped.","u":"2026-12-11T17:00:00Z","k":"t","ty":"visa_travel","h":false,"ar":"Travel","z":"America/New_York","w":"Fri Dec 11, 12:00 PM ET"},{"i":"g90:zainab-adetayo:TS2-callsheet","a":"staff","o":"Erica","t":"Test shoot 2: send call sheet (Zainab)","d":"Call sheet to Zainab and mother agency: address, call time 9:00 AM Lagos, wardrobe, skin prep and what to eat.","u":"2026-12-11T17:00:00Z","k":"t","ty":"testing","h":false,"ar":"Test shoot","z":"America/New_York","w":"Fri Dec 11, 12:00 PM ET"},{"i":"g90:zainab-adetayo:TS2","a":"model","o":"Zainab Adetayo","t":"Test shoot 2: Zainab","d":"Call time 9:00 AM, wrap about 5:00 PM. Lagos studio. Bring a clean face, hair as discussed, and snacks.","u":"2026-12-14T08:00:00Z","k":"e","ty":"test","h":false,"ar":"Test shoot","z":"Africa/Lagos","w":"Mon Dec 14, 9:00 AM Lagos (Mon Dec 14 3:00 AM ET)","en":"2026-12-14T16:00:00Z","loc":"Lagos studio","ek":""},{"i":"g90:zainab-adetayo:SK2","a":"model","o":"Zainab Adetayo","t":"Skin submission #2 (progress): photos due","d":"Skin submission = 4 photos in daylight by a window, no makeup, no filter, no retouching: front, left, right, and a close-up of any area you want help with. Add three lines: skin type as you see it, any concerns, and any product reaction. A licensed skin professional reviews it. You can choose to share only the photos and not any medical history. Due Mon Dec 14, 5:00 PM Lagos (Mon Dec 14 11:00 AM ET).","u":"2026-12-14T16:00:00Z","k":"t","ty":"progress_submission","h":false,"ar":"Skin","z":"Africa/Lagos","w":"Mon Dec 14, 5:00 PM Lagos (Mon Dec 14 11:00 AM ET)"},{"i":"g90:zainab-adetayo:SK2e","a":"model","o":"Zainab Adetayo","t":"Skin submission #2 due","d":"Upload your skin photos in the portal today.","u":"2026-12-14T16:00:00Z","k":"e","ty":"deadline","h":false,"ar":"Skin","z":"Africa/Lagos","w":"Mon Dec 14, 5:00 PM Lagos (Mon Dec 14 11:00 AM ET)","en":null,"loc":null,"ek":"model meeting"},{"i":"g90:zainab-adetayo:WK2","a":"model","o":"Zainab Adetayo","t":"Walk video #2: send your 20-second walk","d":"Walk practice, 30 minutes, Tuesday and Thursday. Warm up 5 minutes. Straight-line walk of 10 to 15 steps with level eyes and shoulders back, a clean turn at the end, pause, turn back. Practice in the shoe height you expect to wear. Film one 20-second clip from the front and one from the side, phone at hip height, plain background, full body in frame. Your agent gives written feedback and one drill for the next week. Due Mon Dec 14, 5:00 PM Lagos (Mon Dec 14 11:00 AM ET).","u":"2026-12-14T16:00:00Z","k":"t","ty":"training","h":false,"ar":"Walk","z":"Africa/Lagos","w":"Mon Dec 14, 5:00 PM Lagos (Mon Dec 14 11:00 AM ET)"},{"i":"g90:zainab-adetayo:WK2e","a":"model","o":"Zainab Adetayo","t":"Walk practice video #2 due","d":"Send your walk video in the portal today.","u":"2026-12-14T16:00:00Z","k":"e","ty":"training","h":false,"ar":"Walk","z":"Africa/Lagos","w":"Mon Dec 14, 5:00 PM Lagos (Mon Dec 14 11:00 AM ET)","en":null,"loc":null,"ek":"walk practice"},{"i":"g90:zainab-adetayo:TR-fund","a":"staff","o":"Sophia","t":"Release travel advance after approvals (Zainab Adetayo)","d":"Only after the model and mother agency approve. Estimated $8,019.","u":"2026-12-14T17:00:00Z","k":"t","ty":"visa_travel","h":false,"ar":"Travel","z":"America/New_York","w":"Mon Dec 14, 12:00 PM ET"},{"i":"g90:zainab-adetayo:TS1-retouch","a":"staff","o":"Erica","t":"Test shoot 1: retouched finals delivered (Zainab)","d":"Retouched finals saved to the model's media in the portal.","u":"2026-12-15T22:00:00Z","k":"t","ty":"testing","h":true,"ar":"Test shoot","z":"America/New_York","w":"Tue Dec 15, 5:00 PM ET"},{"i":"g90:zainab-adetayo:TS2-selects","a":"staff","o":"Erica","t":"Test shoot 2: send selects (Zainab)","d":"Send the first selects to the model and mother agency for approval.","u":"2026-12-16T22:00:00Z","k":"t","ty":"testing","h":false,"ar":"Test shoot","z":"America/New_York","w":"Wed Dec 16, 5:00 PM ET"},{"i":"g90:zainab-adetayo:TS1-package","a":"staff","o":"Erica","t":"Test shoot 1: add to book and push the package (Zainab)","d":"Add the images to the book and website, then send the package to clients and mother agencies.","u":"2026-12-17T22:00:00Z","k":"t","ty":"testing","h":true,"ar":"Test shoot","z":"America/New_York","w":"Thu Dec 17, 5:00 PM ET"},{"i":"g90:zainab-adetayo:H2","a":"model","o":"Zainab Adetayo","t":"Physical exam and bloodwork: done and cleared","d":"Physical exam and bloodwork as your clinician advises (iron, vitamin D, B12 and thyroid are common for travel season), a dental cleaning and a vision check, all by the dates in your gameplan. You choose what to share: MDV only needs 'cleared' or 'not cleared', never your results. Travel health: ask your clinician about vaccines or medicines for your route, carry a copy of prescriptions, and bring your insurance card. Due Fri Dec 18, 5:00 PM Lagos (Fri Dec 18 11:00 AM ET).","u":"2026-12-18T16:00:00Z","k":"t","ty":"progress_submission","h":true,"ar":"Health","z":"Africa/Lagos","w":"Fri Dec 18, 5:00 PM Lagos (Fri Dec 18 11:00 AM ET)"},{"i":"g90:zainab-adetayo:H2e","a":"model","o":"Zainab Adetayo","t":"Health layout due: physical, dental, vision","d":"Tell your agent you are cleared.","u":"2026-12-18T16:00:00Z","k":"e","ty":"deadline","h":false,"ar":"Health","z":"Africa/Lagos","w":"Fri Dec 18, 5:00 PM Lagos (Fri Dec 18 11:00 AM ET)","en":null,"loc":null,"ek":"model meeting"},{"i":"g90:zainab-adetayo:H3","a":"model","o":"Zainab Adetayo","t":"Dental cleaning and vision check: done","d":"Book both and tell your agent 'done'. Bring glasses or contact prescriptions if you use them.","u":"2026-12-18T16:00:00Z","k":"t","ty":"progress_submission","h":false,"ar":"Health","z":"Africa/Lagos","w":"Fri Dec 18, 5:00 PM Lagos (Fri Dec 18 11:00 AM ET)"},{"i":"g90:zainab-adetayo:TS2-approve","a":"model","o":"Zainab Adetayo","t":"Approve your test shoot 2 selects","d":"Pick your favorites and tell your agent what you do not want used. Tap Complete when done.","u":"2026-12-18T16:00:00Z","k":"t","ty":"testing","h":false,"ar":"Test shoot","z":"Africa/Lagos","w":"Fri Dec 18, 5:00 PM Lagos (Fri Dec 18 11:00 AM ET)"},{"i":"g90:zainab-adetayo:TS2-papprove","a":"partner","o":"Mother agency","t":"Approve test shoot 2 selects (Zainab Adetayo)","d":"Approve the selects or send notes so the retouch can start.","u":"2026-12-18T17:00:00Z","k":"t","ty":"testing","h":false,"ar":"Test shoot","z":"America/New_York","w":"Fri Dec 18, 12:00 PM ET"},{"i":"g90:zainab-adetayo:V5","a":"staff","o":"Troy","t":"VISA DECISION DEADLINE (Zainab Adetayo)","d":"If there is no decision today, escalate to Demontez the same hour and switch to the fallback (Milan placement, or Women's only).","u":"2026-12-21T17:00:00Z","k":"t","ty":"visa_travel","h":true,"ar":"Visa","z":"America/New_York","w":"Mon Dec 21, 12:00 PM ET"},{"i":"g90:zainab-adetayo:TS2-retouch","a":"staff","o":"Erica","t":"Test shoot 2: retouched finals delivered (Zainab)","d":"Retouched finals saved to the model's media in the portal.","u":"2026-12-23T22:00:00Z","k":"t","ty":"testing","h":true,"ar":"Test shoot","z":"America/New_York","w":"Wed Dec 23, 5:00 PM ET"},{"i":"g90:zainab-adetayo:V6","a":"model","o":"Zainab Adetayo","t":"Collect your passport and check the visa","d":"Check name, dates, number of entries and the dates you can stay. Send a photo of the visa page.","u":"2026-12-28T16:00:00Z","k":"t","ty":"visa_travel","h":true,"ar":"Visa","z":"Africa/Lagos","w":"Mon Dec 28, 5:00 PM Lagos (Mon Dec 28 11:00 AM ET)"},{"i":"g90:zainab-adetayo:TS2-package","a":"staff","o":"Erica","t":"Test shoot 2: add to book and push the package (Zainab)","d":"Add the images to the book and website, then send the package to clients and mother agencies.","u":"2026-12-29T22:00:00Z","k":"t","ty":"testing","h":true,"ar":"Test shoot","z":"America/New_York","w":"Tue Dec 29, 5:00 PM ET"},{"i":"g90:zainab-adetayo:TR-tix","a":"staff","o":"Troy","t":"Tickets issued for Zainab Adetayo","d":"Book flights only when the visa (if needed) is in the passport and the travel plan is approved. Send e-tickets to the model and mother agency.","u":"2026-12-30T17:00:00Z","k":"t","ty":"visa_travel","h":true,"ar":"Travel","z":"America/New_York","w":"Wed Dec 30, 12:00 PM ET"},{"i":"g90:zainab-adetayo:SK3","a":"model","o":"Zainab Adetayo","t":"Skin submission #3 (pre-show): photos due","d":"Skin submission = 4 photos in daylight by a window, no makeup, no filter, no retouching: front, left, right, and a close-up of any area you want help with. Add three lines: skin type as you see it, any concerns, and any product reaction. A licensed skin professional reviews it. You can choose to share only the photos and not any medical history. Due Mon Jan 4, 5:00 PM Lagos (Mon Jan 4 11:00 AM ET).","u":"2027-01-04T16:00:00Z","k":"t","ty":"progress_submission","h":false,"ar":"Skin","z":"Africa/Lagos","w":"Mon Jan 4, 5:00 PM Lagos (Mon Jan 4 11:00 AM ET)"},{"i":"g90:zainab-adetayo:SK3e","a":"model","o":"Zainab Adetayo","t":"Skin submission #3 due","d":"Upload your skin photos in the portal today.","u":"2027-01-04T16:00:00Z","k":"e","ty":"deadline","h":false,"ar":"Skin","z":"Africa/Lagos","w":"Mon Jan 4, 5:00 PM Lagos (Mon Jan 4 11:00 AM ET)","en":null,"loc":null,"ek":"model meeting"},{"i":"g90:zainab-adetayo:WK3","a":"model","o":"Zainab Adetayo","t":"Walk video #3: send your 20-second walk","d":"Walk practice, 30 minutes, Tuesday and Thursday. Warm up 5 minutes. Straight-line walk of 10 to 15 steps with level eyes and shoulders back, a clean turn at the end, pause, turn back. Practice in the shoe height you expect to wear. Film one 20-second clip from the front and one from the side, phone at hip height, plain background, full body in frame. Your agent gives written feedback and one drill for the next week. Due Mon Jan 4, 5:00 PM Lagos (Mon Jan 4 11:00 AM ET).","u":"2027-01-04T16:00:00Z","k":"t","ty":"training","h":false,"ar":"Walk","z":"Africa/Lagos","w":"Mon Jan 4, 5:00 PM Lagos (Mon Jan 4 11:00 AM ET)"},{"i":"g90:zainab-adetayo:WK3e","a":"model","o":"Zainab Adetayo","t":"Walk practice video #3 due","d":"Send your walk video in the portal today.","u":"2027-01-04T16:00:00Z","k":"e","ty":"training","h":false,"ar":"Walk","z":"Africa/Lagos","w":"Mon Jan 4, 5:00 PM Lagos (Mon Jan 4 11:00 AM ET)","en":null,"loc":null,"ek":"walk practice"},{"i":"g90:zainab-adetayo:PA6","a":"partner","o":"Mother agency","t":"Confirm arrival date and emergency contact (Zainab Adetayo)","d":"Arrival Sun Jan 10, 2027. Confirm the contact and, for anyone under 18, the guardian.","u":"2027-01-04T17:00:00Z","k":"t","ty":"visa_travel","h":false,"ar":"Travel","z":"America/New_York","w":"Mon Jan 4, 12:00 PM ET"},{"i":"g90:zainab-adetayo:TR-house","a":"staff","o":"Troy","t":"Housing confirmed and address sent (Zainab Adetayo)","d":"Confirm the bed, key pickup and house rules and send them to the model and mother agency.","u":"2027-01-04T17:00:00Z","k":"t","ty":"visa_travel","h":false,"ar":"Travel","z":"America/New_York","w":"Mon Jan 4, 12:00 PM ET"},{"i":"g90:zainab-adetayo:CK1","a":"model","o":"Zainab Adetayo","t":"Mid-season check-in call with your agent","d":"30 minutes: how you feel, sleep, food, skin, walk and travel. Bring questions.","u":"2027-01-06T16:00:00Z","k":"e","ty":"meeting","h":false,"ar":"Health","z":"Africa/Lagos","w":"Wed Jan 6, 5:00 PM Lagos (Wed Jan 6 11:00 AM ET)","en":"2027-01-06T16:30:00Z","loc":null,"ek":"model meeting"},{"i":"g90:zainab-adetayo:TR-ready","a":"model","o":"Zainab Adetayo","t":"Pre-flight check: documents, health and packing","d":"Passport, visa, tickets, insurance card, prescriptions, charger, walking shoes and your skin kit. Confirm you are ready.","u":"2027-01-07T16:00:00Z","k":"t","ty":"visa_travel","h":false,"ar":"Travel","z":"Africa/Lagos","w":"Thu Jan 7, 5:00 PM Lagos (Thu Jan 7 11:00 AM ET)"},{"i":"g90:zainab-adetayo:TR-arr","a":"model","o":"Zainab Adetayo","t":"Arrival: Zainab lands","d":"Landing in Paris. Airport pickup and address are in your gameplan.","u":"2027-01-10T11:00:00Z","k":"e","ty":"travel","h":false,"ar":"Travel","z":"Europe/Paris","w":"Sun Jan 10, 12:00 PM Paris (Sun Jan 10 6:00 AM ET)","en":null,"loc":"Paris","ek":"arrival"},{"i":"g90:zainab-adetayo:WKOFF","a":"model","o":"Zainab Adetayo","t":"Walk-off with your agent (Zainab)","d":"In-person walk check with your agent: straight walk, turns, pace and shoes. About 45 minutes.","u":"2027-01-11T09:00:00Z","k":"e","ty":"training","h":false,"ar":"Walk","z":"Europe/Paris","w":"Mon Jan 11, 10:00 AM Paris (Mon Jan 11 4:00 AM ET)","en":"2027-01-11T09:45:00Z","loc":"Paris","ek":"walk practice"},{"i":"g90:zainab-adetayo:DG","a":"model","o":"Zainab Adetayo","t":"Digitals session (Zainab)","d":"Fresh digitals for casting: clean face, fitted plain clothes, hair back, no jewelry. Front, profile, back, full length, smile and walk video.","u":"2027-01-13T10:00:00Z","k":"e","ty":"test","h":false,"ar":"Digitals","z":"Europe/Paris","w":"Wed Jan 13, 11:00 AM Paris (Wed Jan 13 5:00 AM ET)","en":"2027-01-13T12:00:00Z","loc":"Paris","ek":"digitals"},{"i":"g90:zainab-adetayo:DGu","a":"staff","o":"Erica","t":"Digitals up and comp card updated (Zainab Adetayo)","d":"Upload the digitals, update the comp card and measurements, and tell the mother agency.","u":"2027-01-15T22:00:00Z","k":"t","ty":"progress_submission","h":true,"ar":"Digitals","z":"America/New_York","w":"Fri Jan 15, 5:00 PM ET"},{"i":"g90:zainab-adetayo:DGs","a":"staff","o":"Erica","t":"Digitals sent to mother agency and top clients (Zainab Adetayo)","d":"Send the new digitals to the mother agency and the casting directors on this season's list.","u":"2027-01-18T22:00:00Z","k":"t","ty":"casting_show","h":false,"ar":"Digitals","z":"America/New_York","w":"Mon Jan 18, 5:00 PM ET"},{"i":"g90:zainab-adetayo:SK4","a":"model","o":"Zainab Adetayo","t":"Skin submission #4 (check): photos due","d":"Skin submission = 4 photos in daylight by a window, no makeup, no filter, no retouching: front, left, right, and a close-up of any area you want help with. Add three lines: skin type as you see it, any concerns, and any product reaction. A licensed skin professional reviews it. You can choose to share only the photos and not any medical history. Due Mon Feb 1, 5:00 PM Lagos (Mon Feb 1 11:00 AM ET).","u":"2027-02-01T16:00:00Z","k":"t","ty":"progress_submission","h":false,"ar":"Skin","z":"Africa/Lagos","w":"Mon Feb 1, 5:00 PM Lagos (Mon Feb 1 11:00 AM ET)"},{"i":"g90:zainab-adetayo:SK4e","a":"model","o":"Zainab Adetayo","t":"Skin submission #4 due","d":"Upload your skin photos in the portal today.","u":"2027-02-01T16:00:00Z","k":"e","ty":"deadline","h":false,"ar":"Skin","z":"Africa/Lagos","w":"Mon Feb 1, 5:00 PM Lagos (Mon Feb 1 11:00 AM ET)","en":null,"loc":null,"ek":"model meeting"}]}]}$json$;
  org uuid; boss uuid; mem jsonb := '{}'::jsonb;
  m jsonb; it jsonb; mid uuid; gp uuid; dp uuid; pa uuid; st text; r text;
  n_models int := 0; n_task int := 0; n_event int := 0; n_skip int := 0;
  miss text := ''; nomem text := ''; pmeta jsonb; ppfound boolean; n_ds int := 0;
begin
  select id into org from public.organizations where slug = 'maison-de-veux';
  if org is null then raise exception 'Organization maison-de-veux was not found'; end if;
  select id into boss from auth.users where lower(email) = 'demontez@maisondeveux.com';
  select coalesce(jsonb_object_agg(k, v), '{}'::jsonb) into mem from (
    select lower(split_part(pr.display_name, ' ', 1)) k, om.id::text v
    from public.organization_members om join public.profiles pr on pr.user_id = om.user_id
    where om.organization_id = org and om.member_type = 'staff' and om.status = 'active') s;

  for m in select * from jsonb_array_elements(p->'models') loop
    select id into mid from public.models where organization_id = org and pg_temp.nm(display_name) = pg_temp.nm(m->>'name') limit 1;
    if mid is null then miss := miss || (m->>'name') || '; '; continue; end if;
    n_models := n_models + 1;

    select id, development_plan_id, status into gp, dp, st from public.model_gameplans where organization_id = org and model_id = mid limit 1;
    if gp is null then
      insert into public.model_gameplans (organization_id, model_id, status, title, key_date, key_date_label, welcome_message, brand_positioning, market_focus, image_rules, risks, checkin_cadence, created_by)
      values (org, mid, 'active', m->'gp'->>'title', (m->'gp'->>'key_date')::date, m->'gp'->>'key_label', m->'gp'->>'welcome', m->'gp'->>'positioning',
              m->'gp'->>'market', m->'gp'->>'image_rules', m->'gp'->>'risks', m->'gp'->'cadence', boss)
      returning id into gp;
      dp := null;
    else
      update public.model_gameplans set status = 'active',
             title = coalesce(title, m->'gp'->>'title'), key_date = coalesce(key_date, (m->'gp'->>'key_date')::date),
             key_date_label = coalesce(key_date_label, m->'gp'->>'key_label'), welcome_message = coalesce(welcome_message, m->'gp'->>'welcome'),
             brand_positioning = coalesce(brand_positioning, m->'gp'->>'positioning'), market_focus = coalesce(market_focus, m->'gp'->>'market'),
             image_rules = coalesce(image_rules, m->'gp'->>'image_rules'), risks = coalesce(risks, m->'gp'->>'risks'), updated_at = now()
      where id = gp;
    end if;
    if dp is null then
      insert into public.development_plans (organization_id, model_id, title, status, starts_on, target_date, summary, metadata)
      values (org, mid, m->'gp'->>'title', 'active', date '2026-11-08', (m->'gp'->>'key_date')::date, m->'gp'->>'positioning',
              jsonb_build_object('source', 'smart_gameplan', 'gameplan_id', gp, 'plan', 'g90'))
      returning id into dp;
      update public.model_gameplans set development_plan_id = dp where id = gp;
    end if;

    -- daily routine blocks, habits and weekly items for the model's own DaySilk (kept beside their plan, so re-saving their answers never removes them)
    -- model_private_profiles has no id column: a row is identified by organization_id + model_id
    select metadata into pmeta from public.model_private_profiles where organization_id = org and model_id = mid limit 1;
    ppfound := found;
    pmeta := jsonb_set(coalesce(pmeta, '{}'::jsonb), '{daysilk}', coalesce(pmeta->'daysilk', '{}'::jsonb) || jsonb_build_object('gameplan', m->'ds'), true);
    if not ppfound then
      insert into public.model_private_profiles (organization_id, model_id, metadata) values (org, mid, pmeta);
    else
      update public.model_private_profiles set metadata = pmeta where organization_id = org and model_id = mid;
    end if;
    n_ds := n_ds + 1;

    select partner_agency_id into pa from public.model_placements
      where organization_id = org and model_id = mid and status in ('active', 'pending', 'placed') order by created_at desc limit 1;

    for it in select * from jsonb_array_elements(m->'items') loop
      r := pg_temp.gp_item(org, boss, mid, gp, pa, it, mem);
      if r = 'task' then n_task := n_task + 1;
      elsif r = 'event' then n_event := n_event + 1;
      elsif r like 'task:nomember:%' then n_task := n_task + 1; nomem := nomem || substr(r, 15) || ' ';
      else n_skip := n_skip + 1; end if;
    end loop;
  end loop;

  raise notice 'Models loaded: %. Tasks: %. Calendar events: %. DaySilk routine blocks written for: %. Skipped (no mother agency placement on file): %.', n_models, n_task, n_event, n_ds, n_skip;
  if miss <> '' then raise notice 'Models NOT found by name (fix the name in Models and run again): %', miss; end if;
  if nomem <> '' then raise notice 'Team names with no matching active staff (first names): %', (select string_agg(distinct x, ', ') from unnest(string_to_array(trim(nomem), ' ')) x); end if;
end $gp$;
